// Create inserts a complete model from explicit draft fields. Omitted UUID primary keys are generated unless the database owns their default or a distinct mutation input is required.
func (q FileQuery) Create(ctx context.Context, writer database.Transactor, draft FileDraft) (File, error) {
	mutation, err := draft.foundryMutation(true)
	if err != nil {
		return File{}, err
	}
	return q.Query.Insert(ctx, writer, mutation)
}

// Upsert inserts or applies an explicit typed conflict policy. Skipped conflicts return an omitted result; database constraints still apply.
func (q FileQuery) Upsert(ctx context.Context, writer database.Transactor, draft FileDraft, conflict foundryquery.Conflict[File]) (foundryvalue.Optional[File], error) {
	mutation, err := draft.foundryMutation(true)
	if err != nil {
		return foundryvalue.Optional[File]{}, err
	}
	return q.Query.InsertOnConflict(ctx, writer, mutation, conflict)
}

// CreateMany inserts a bounded batch atomically. A valid empty batch performs no database work. This is a set-based write.
func (q FileQuery) CreateMany(ctx context.Context, writer database.Transactor, drafts []FileDraft) ([]File, error) {
	return q.foundryInsertMany(ctx, writer, drafts, nil)
}

// UpsertMany applies one typed conflict policy to a bounded atomic batch. Skipped conflicts have no returned model; result order is not an input-row mapping.
func (q FileQuery) UpsertMany(ctx context.Context, writer database.Transactor, drafts []FileDraft, conflict foundryquery.Conflict[File]) ([]File, error) {
	return q.foundryInsertMany(ctx, writer, drafts, &conflict)
}
func (q FileQuery) foundryInsertMany(ctx context.Context, writer database.Transactor, drafts []FileDraft, conflict *foundryquery.Conflict[File]) ([]File, error) {
	mutations, err := q.foundryCreateMutations(drafts)
	if err != nil {
		return nil, err
	}
	if conflict == nil {
		return q.Query.InsertMany(ctx, writer, mutations)
	}
	return q.Query.InsertManyOnConflict(ctx, writer, mutations, *conflict)
}
func (q FileQuery) foundryCreateMutations(drafts []FileDraft) ([]foundryquery.Mutation[File], error) {
	if len(drafts) > foundryquery.MaxInsertRows {
		return nil, foundryfault.New(foundryfault.Invalid, "model insert exceeds its row bound")
	}
	mutations := make([]foundryquery.Mutation[File], len(drafts))
	for i, draft := range drafts {
		m, err := draft.foundryMutation(true)
		if err != nil {
			return nil, err
		}
		mutations[i] = m
	}
	return mutations, nil
}

// Update patches one typed primary key within this query's filters. Omitted fields stay unchanged; primary-key mutation is rejected.
func (q FileQuery) Update(ctx context.Context, writer database.Transactor, key model.ID[File], draft FileDraft) (File, error) {
	mutation, err := draft.foundryMutation(false)
	if err != nil {
		return File{}, err
	}
	return q.Where(FileFields().ID.Eq(key)).Query.Patch(ctx, writer, mutation)
}

// Delete removes one typed primary key within this query's filters and returns its complete pre-deletion model.
func (q FileQuery) Delete(ctx context.Context, writer database.Transactor, key model.ID[File]) (File, error) {
	return q.Where(FileFields().ID.Eq(key)).Query.Remove(ctx, writer)
}

// CreateEach creates each input through normal model hooks and mutators inside one bounded atomic operation. Results preserve input order; CreateMany has separate set-based semantics.
func (q FileQuery) CreateEach(ctx context.Context, writer database.Transactor, drafts []FileDraft) ([]File, error) {
	mutations, err := q.foundryCreateMutations(drafts)
	if err != nil {
		return nil, err
	}
	return q.Query.InsertEach(ctx, writer, mutations)
}

// UpdateEach derives a concrete draft for each locked model and runs its normal lifecycle. The complete matching set must fit limit before any callback. Results follow primary-key order and all selected writes are atomic; read ordering, pagination and eager-loading options are rejected.
func (q FileQuery) UpdateEach(ctx context.Context, writer database.Transactor, limit int, draft func(context.Context, *database.Tx, File) (FileDraft, error)) ([]File, error) {
	var callback func(context.Context, *database.Tx, File) (foundryquery.Mutation[File], error)
	if draft != nil {
		callback = func(ctx context.Context, tx *database.Tx, current File) (foundryquery.Mutation[File], error) {
			d, err := draft(ctx, tx, current)
			if err != nil {
				return foundryquery.Mutation[File]{}, err
			}
			return d.foundryMutation(false)
		}
	}
	return q.Query.PatchEach(ctx, writer, limit, callback)
}

// DeleteEach deletes each selected active model through normal lifecycle behavior. Soft-delete models remain stored; other models are physically removed. The positive limit bounds the complete atomic candidate set before hooks run.
func (q FileQuery) DeleteEach(ctx context.Context, writer database.Transactor, limit int) ([]File, error) {
	return q.Query.RemoveEach(ctx, writer, limit)
}

// FirstOrCreate returns the first primary-ordered matching model or creates one through its normal lifecycle. The draft is prepared only when no model matches; omitted fields default from the query's top-level equality filters and global scopes, and the stored creation must satisfy the query. Internal lookup skips Retrieved. Concurrent absence relies on database unique constraints and reports ordinary conflicts without hidden retries.
func (q FileQuery) FirstOrCreate(ctx context.Context, writer database.Transactor, create FileDraft) (File, error) {
	return q.Query.FirstOrInsert(ctx, writer, create)
}

// CreateOrFirst creates a model through its normal lifecycle and, when a unique constraint rejects it, returns the first primary-ordered model matching the query instead. The insert runs in its own savepoint, so a concurrent creation of the same unique key is resolved under READ COMMITTED rather than reported. The query must select the row holding the conflicting key; a created model must satisfy it.
func (q FileQuery) CreateOrFirst(ctx context.Context, writer database.Transactor, create FileDraft) (File, error) {
	return q.Query.InsertOrFirst(ctx, writer, create)
}

// UpdateOrCreate runs a concrete draft callback for the first primary-ordered matching model or creates from the separate creation draft. Only the chosen branch prepares its draft; ordinary lifecycle and transaction ownership remain in force. Read ordering, pagination and eager-loading options are rejected.
func (q FileQuery) UpdateOrCreate(ctx context.Context, writer database.Transactor, create FileDraft, draft func(context.Context, *database.Tx, File) (FileDraft, error)) (File, error) {
	var callback func(context.Context, *database.Tx, File) (foundryquery.Mutation[File], error)
	if draft != nil {
		callback = func(ctx context.Context, tx *database.Tx, current File) (foundryquery.Mutation[File], error) {
			d, err := draft(ctx, tx, current)
			if err != nil {
				return foundryquery.Mutation[File]{}, err
			}
			return d.foundryMutation(false)
		}
	}
	return q.Query.PatchOrInsert(ctx, writer, create, callback)
}

